        text.push_str(&err);
    }
    if out.status.success() {
        Ok(text)
    } else {
        Err(if text.is_empty() { format!("git {} ist fehlgeschlagen", args.join(" ")) } else { text })
    }
}

/// Top folder of the git repository that contains `dir`.
pub fn repo_root(dir: &Path) -> Option<PathBuf> {
    if !dir.is_dir() {
        return None;
    }
    run(dir, &["rev-parse", "--show-toplevel"]).ok().map(|s| PathBuf::from(s.trim()))
}

/// The repository for a profile: the configured one, else the one holding the sync folder,
/// else the one holding the data folder.
pub fn repo_for(cfg: &Config) -> Result<PathBuf, String> {
    if !cfg.git_repo.as_os_str().is_empty() {
        return repo_root(&cfg.git_repo)
            .ok_or_else(|| format!("{} ist kein Git-Repository.", cfg.git_repo.display()));
    }
    if !cfg.sync_dir.as_os_str().is_empty() {
        if let Some(r) = repo_root(&cfg.sync_dir) {
            return Ok(r);
        }
    }
    repo_root(&cfg.data_dir).ok_or_else(|| {
        "Kein Git-Repository gefunden. Der Sync-Ordner (der content-Ordner deines Hugo-Blogs) sollte in einem Git-Repository liegen – oder in den Einstellungen ein Git-Repository eintragen.".into()
    })
}

/// Paths that hold blog content for this profile, relative to `repo`
/// (content folder, transactions, snippets.json, tags.json). Empty = whole repository.
pub fn scope(cfg: &Config, repo: &Path) -> Vec<String> {
    if !cfg.git_blog_only {
        return vec![];
    }
    let canon = |p: &Path| std::fs::canonicalize(p).unwrap_or_else(|_| p.to_path_buf());
    let repo = canon(repo);
    let (content, meta) = if !cfg.sync_dir.as_os_str().is_empty() && canon(&cfg.sync_dir).starts_with(&repo) {
        (cfg.sync_dir.clone(), store::meta_of(&cfg.sync_dir))
    } else {
        (cfg.content_root(), cfg.meta_dir())
    };
    let mut out = Vec::new();
    for p in [
        content,
        meta.join(store::TX_DIR),
        store::snippets_path(&meta),
        meta.join("tags.json"),
    ] {
        let abs = canon(&p);
        if let Ok(rel) = abs.strip_prefix(&repo) {
            let rel = rel.to_string_lossy().to_string();
            if p.exists() && !out.contains(&rel) {
                out.push(if rel.is_empty() { ".".into() } else { rel });
            }
        }
    }
    out
}

#[derive(Clone, Copy, Debug, PartialEq)]
pub enum Kind {
    Created,
    Changed,
    Deleted,
}

impl Kind {
    pub fn label(self) -> &'static str {
        match self {
            Kind::Created => "Neu",
            Kind::Changed => "Geändert",
            Kind::Deleted => "Gelöscht",
        }
    }
}

#[derive(Clone, Debug)]
pub struct Change {
    pub kind: Kind,
    /// article folder, relative to the repository
    pub dir: String,
    pub title: String,
    pub modified: Option<SystemTime>,
}

#[derive(Clone, Debug, Default)]
pub struct Status {
    /// `main...origin/main [ahead 1]`
    pub branch: String,
    pub ahead: u32,
    pub behind: u32,
    pub changes: Vec<Change>,
    /// changed files that are not articles (transactions, snippets.json …)
    pub other: Vec<String>,
}

impl Status {
    pub fn is_clean(&self) -> bool {
        self.changes.is_empty() && self.other.is_empty()
    }
}

fn title_of(text: &str, dir: &str) -> String {
    let a = store::parse_article(text, dir, &Config::default());
    if a.title.trim().is_empty() {
        dir.rsplit('/').next().unwrap_or(dir).to_string()
    } else {
        a.title.trim().to_string()
    }
}

/// What changed since the last commit, grouped by article.
pub fn status(repo: &Path, scope: &[String]) -> Result<Status, String> {
    let mut st = Status::default();
    if let Ok(head) = run(repo, &["status", "-sb", "--porcelain=v1"]) {
        let first = head.lines().next().unwrap_or("").trim_start_matches("## ").to_string();
        let num = |key: &str| -> u32 {
            first
                .split(key)
                .nth(1)
                .and_then(|r| r.split(|c: char| !c.is_ascii_digit()).next())
                .and_then(|n| n.parse().ok())
                .unwrap_or(0)
        };
        st.ahead = num("ahead ");
        st.behind = num("behind ");
        st.branch = first;
    }
    let mut args = vec!["status", "--porcelain=v1", "-z", "--untracked-files=all"];
    if !scope.is_empty() {
        args.push("--");
        args.extend(scope.iter().map(|s| s.as_str()));
    }
    let raw = run(repo, &args)?;
    // file -> (index of status char: '?', 'A', 'D' or 'M')
    let mut files: Vec<(String, char)> = Vec::new();
    let mut parts = raw.split('\0');
    while let Some(entry) = parts.next() {
        if entry.len() < 4 {
            continue;
        }
        let (x, y) = (entry.as_bytes()[0] as char, entry.as_bytes()[1] as char);
        let path = entry[3..].to_string();
        if x == 'R' || x == 'C' {
            parts.next(); // source path of a rename
        }
        let kind = if x == '?' || x == 'A' {
            'A'
        } else if x == 'D' || y == 'D' {
            'D'
        } else {
            'M'
        };
        files.push((path, kind));
    }

    let in_head = |p: &str| run(repo, &["cat-file", "-e", &format!("HEAD:{p}")]).is_ok();
    let mut dirs: BTreeMap<String, Kind> = BTreeMap::new();
    for (path, k) in &files {
        let (dir, name) = match path.rfind('/') {
            Some(i) => (path[..i].to_string(), &path[i + 1..]),
            None => (String::new(), path.as_str()),
        };
        if name == "index.md" {
            let kind = match k {
                'A' => Kind::Created,
                'D' => Kind::Deleted,
                _ => Kind::Changed,
            };
            dirs.insert(dir, kind);
        } else if !dir.is_empty()
            && (repo.join(&dir).join("index.md").is_file() || in_head(&format!("{dir}/index.md")))
        {
            dirs.entry(dir).or_insert(Kind::Changed);
        } else {
            st.other.push(path.clone());
        }
    }
    for (dir, kind) in dirs {
        let file = repo.join(&dir).join("index.md");
        let (title, modified) = if kind == Kind::Deleted {
            let old = run(repo, &["show", &format!("HEAD:{dir}/index.md")]).unwrap_or_default();
            (title_of(&old, &dir), None)
        } else {
            let text = std::fs::read_to_string(&file).unwrap_or_default();
            (title_of(&text, &dir), std::fs::metadata(&file).and_then(|m| m.modified()).ok())
        };
        st.changes.push(Change { kind, dir, title, modified });
    }
    // newest first
    st.changes.sort_by(|a, b| b.modified.cmp(&a.modified));
    Ok(st)
}

/// Commit message: the title of the last changed entry, then what was created, changed, deleted.
pub fn commit_message(st: &Status) -> String {
    let last = st
        .changes
        .iter()
        .filter(|c| c.kind != Kind::Deleted)
        .max_by_key(|c| c.modified)
        .or_else(|| st.changes.first());
    let mut subject = match last {
        Some(c) => c.title.clone(),
        None if !st.other.is_empty() => "hmb: Transaktionen und Einstellungen".to_string(),
        None => String::new(),
    };
    if st.changes.len() > 1 {
        subject.push_str(&format!(" (+{} weitere)", st.changes.len() - 1));
    }
    let mut body = String::new();
    for kind in [Kind::Created, Kind::Changed, Kind::Deleted] {
        let list: Vec<&Change> = st.changes.iter().filter(|c| c.kind == kind).collect();
        if list.is_empty() {
            continue;
        }
        body.push_str(&format!("\n{}:\n", kind.label()));
        for c in list {
            body.push_str(&format!("- {} ({})\n", c.title, c.dir));
        }
    }
    if !st.other.is_empty() {
        body.push_str(&format!("\nSonstiges: {} Datei(en) (Transaktionen, Snippets, Tags)\n", st.other.len()));
    }
    if body.is_empty() {
        subject
    } else {
        format!("{subject}\n{body}").trim_end().to_string()
    }
}

/// Pull with rebase; local uncommitted changes are put aside and restored.
pub fn pull(repo: &Path) -> Result<String, String> {
    run(repo, &["pull", "--rebase", "--autostash"])
}

/// Stages the blog content (or everything) and commits with `message`.
pub fn commit(repo: &Path, scope: &[String], message: &str) -> Result<String, String> {
    let mut add = vec!["add", "-A"];
    if !scope.is_empty() {
        add.push("--");
        add.extend(scope.iter().map(|s| s.as_str()));
    }
    let added = run(repo, &add)?;
    let out = run(repo, &["commit", "-m", message])?;
    Ok(if added.is_empty() { out } else { format!("{added}\n{out}") })
}

/// Push; sets the upstream on the first push of a branch.
pub fn push(repo: &Path) -> Result<String, String> {
    if run(repo, &["rev-parse", "--abbrev-ref", "--symbolic-full-name", "@{u}"]).is_ok() {
        run(repo, &["push"])
    } else {
        run(repo, &["push", "-u", "origin", "HEAD"])
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::fs;

    #[test]
    fn status_message_commit_push_with_local_remote() {
        let t = std::env::temp_dir().join(format!("hmb-git-{}", std::process::id()));
        let _ = fs::remove_dir_all(&t);
        let (remote, repo) = (t.join("remote.git"), t.join("blog"));
        fs::create_dir_all(&t).unwrap();
        run(&t, &["init", "-q", "--bare", remote.to_str().unwrap()]).unwrap();
        run(&t, &["init", "-q", repo.to_str().unwrap()]).unwrap();
        for (k, v) in [("user.name", "Test"), ("user.email", "t@example.org")] {
            run(&repo, &["config", k, v]).unwrap();
        }
        run(&repo, &["remote", "add", "origin", remote.to_str().unwrap()]).unwrap();
        let w = |p: &str, s: &str| {
            let f = repo.join(p);
            fs::create_dir_all(f.parent().unwrap()).unwrap();
            fs::write(f, s).unwrap();
        };
        w("content/a/alt/index.md", "---\ntitle: Alter Artikel\n---\nx\n");
        w("content/a/weg/index.md", "---\ntitle: Wird gelöscht\n---\nx\n");
        w("public/index.html", "build output");
        run(&repo, &["add", "-A"]).unwrap();
        run(&repo, &["commit", "-q", "-m", "start"]).unwrap();
        // changes: one new (with image), one changed, one deleted, one transaction, one non-blog file
        w("content/b/neu/index.md", "---\ntitle: Ganz neu\n---\nx\n");
        w("content/b/neu/bild.png", "png");
        std::thread::sleep(std::time::Duration::from_millis(20));
        w("content/a/alt/index.md", "---\ntitle: Alter Artikel\n---\ny\n");
        fs::remove_dir_all(repo.join("content/a/weg")).unwrap();
        w("transactions/transaction-2026-11-27-10-00.json", "{}");
        w("public/index.html", "changed build output");

        let cfg = Config { sync_dir: repo.join("content"), git_blog_only: true, ..Default::default() };
        let sc = scope(&cfg, &repo);
        assert_eq!(sc, vec!["content".to_string(), "transactions".to_string()]);
        let st = status(&repo, &sc).unwrap();
        let kinds: Vec<(Kind, &str)> = st.changes.iter().map(|c| (c.kind, c.title.as_str())).collect();
        println!("{kinds:?} other={:?}", st.other);
        assert!(kinds.contains(&(Kind::Created, "Ganz neu")));
        assert!(kinds.contains(&(Kind::Changed, "Alter Artikel")));
        assert!(kinds.contains(&(Kind::Deleted, "Wird gelöscht")));
        assert_eq!(st.other, vec!["transactions/transaction-2026-11-27-10-00.json".to_string()]);
        let msg = commit_message(&st);
        println!("{msg}");
        assert!(msg.starts_with("Alter Artikel (+2 weitere)"), "last changed entry first: {msg}");
        assert!(msg.contains("Neu:\n- Ganz neu (content/b/neu)"));
        assert!(msg.contains("Gelöscht:\n- Wird gelöscht (content/a/weg)"));

        commit(&repo, &sc, &msg).unwrap();
        let after = status(&repo, &sc).unwrap();
        assert!(after.is_clean());
        // the non-blog file stays uncommitted
        assert!(run(&repo, &["status", "--porcelain"]).unwrap().contains("public/index.html"));
        let pushed = push(&repo).unwrap();
        println!("{pushed}");
        assert!(run(&remote, &["log", "--oneline", "-1"]).unwrap().contains("Alter Artikel"));
        assert!(pull(&repo).is_ok());
        let _ = fs::remove_dir_all(&t);
    }
}

//! Git window (button "Git" in the top bar): Pull, then Commit with a prepared message
//! (title of the last changed entry + what was created, changed, deleted), then Push.
//! Git runs in a thread; its output is shown in the window.

use super::*;
use crate::gitops::{self, Kind};
use eframe::egui::{CornerRadius, Margin, RichText, Stroke, Vec2};

#[derive(Clone, Copy, Debug, PartialEq)]
pub enum Step {
    Pull,
    Commit,
    Push,
}

impl Step {
    fn label(self) -> &'static str {
        match self {
            Step::Pull => "git pull",
            Step::Commit => "git commit",
            Step::Push => "git push",
        }
    }
}

pub struct LogLine {
    pub cmd: String,
    pub out: String,
    pub ok: bool,
}

#[derive(Default)]
pub struct GitState {
    pub open: bool,
    pub repo: Option<PathBuf>,
    pub repo_err: Option<String>,
    pub status: gitops::Status,
    pub message: String,
    pub message_edited: bool,
    pub log: Vec<LogLine>,
    pub running: Option<(Step, Receiver<Result<String, String>>)>,
    pub pulled: bool,
}

impl GitState {
    pub fn busy(&self) -> bool {
        self.running.is_some()
    }
}

impl HmbApp {
    pub(super) fn open_git(&mut self) {
        self.save_current();
        self.git.open = true;
        self.git_refresh();
    }

    /// Reads repository, branch and changes again; prepares the commit message.
    fn git_refresh(&mut self) {
        match gitops::repo_for(&self.cfg) {
            Ok(repo) => {
                let scope = gitops::scope(&self.cfg, &repo);
                match gitops::status(&repo, &scope) {
                    Ok(st) => {
                        if !self.git.message_edited {
                            self.git.message = gitops::commit_message(&st);
                        }
                        self.git.status = st;
                        self.git.repo_err = None;
                    }
                    Err(e) => self.git.repo_err = Some(e),
                }
                self.git.repo = Some(repo);
            }
            Err(e) => {
                self.git.repo = None;
                self.git.repo_err = Some(e);
            }
        }
    }

    fn git_start(&mut self, ctx: &egui::Context, step: Step) {
        let Some(repo) = self.git.repo.clone() else { return };
        if self.git.busy() {
            return;
        }
        let scope = gitops::scope(&self.cfg, &repo);
        let message = self.git.message.trim().to_string();
        let (tx, rx) = channel();
        let ctx2 = ctx.clone();
        std::thread::spawn(move || {
            let r = match step {
                Step::Pull => gitops::pull(&repo),
                Step::Commit => gitops::commit(&repo, &scope, &message),
                Step::Push => gitops::push(&repo),
            };
            let _ = tx.send(r);
            ctx2.request_repaint();
        });
        self.git.running = Some((step, rx));
        self.set_status(format!("{} läuft …", step.label()), true);
    }

    /// Called every frame: takes the result of a finished git command.
    pub(super) fn poll_git(&mut self) {
        let Some((step, rx)) = &self.git.running else { return };
        let step = *step;
        let res = match rx.try_recv() {
            Ok(r) => r,
            Err(std::sync::mpsc::TryRecvError::Empty) => return,
            Err(_) => Err("abgebrochen".into()),
        };
        self.git.running = None;
        let ok = res.is_ok();
        let out = match &res {
            Ok(s) if s.trim().is_empty() => "fertig".to_string(),
            Ok(s) | Err(s) => s.clone(),
        };
        self.git.log.push(LogLine { cmd: step.label().into(), out: out.clone(), ok });
        match (step, ok) {
            (Step::Pull, true) => {
                self.git.pulled = true;
                self.set_status("git pull fertig – jetzt synchronisieren, um neue Artikel in die App zu holen.", true);
            }
            (Step::Commit, true) => {
                self.git.message_edited = false;
                self.set_status("Commit gespeichert – jetzt pushen.", true);
            }
            (Step::Push, true) => {
                let last = out.lines().last().unwrap_or("").trim().to_string();
                self.set_status(format!("Gepusht. {last}"), true);
            }
            (_, false) => {
                let first = out.lines().next().unwrap_or("").to_string();
                self.set_status(format!("{} fehlgeschlagen: {first}", step.label()), false);
            }
        }
        self.git_refresh();
    }

    pub(super) fn git_window(&mut self, ctx: &egui::Context) {
        if !self.git.open {
            return;
        }
        let mut open = true;
        let mut action: Option<Step> = None;
        let mut refresh = false;
        let mut sync_now = false;
        let mut reset_msg = false;
        let mut scope_changed = false;
        let busy = self.git.busy();
        let running = self.git.running.as_ref().map(|(s, _)| *s);
        let title = format!("Git – {}", self.cfg.title);
        egui::Window::new(title)
            .id(egui::Id::new("git_window"))
            .open(&mut open)
            .default_width(640.0)
            .default_height(560.0)
            .collapsible(false)
            .show(ctx, |ui| {
                // repository and branch
                match &self.git.repo {
                    Some(repo) => {
                        ui.horizontal(|ui| {
                            ui.label(RichText::new("Repository").color(MUTED));
                            ui.label(RichText::new(widgets::show_path(repo)).monospace().color(INK));
                        });
                        ui.horizontal(|ui| {
                            ui.label(RichText::new("Branch").color(MUTED));
                            ui.label(RichText::new(&self.git.status.branch).monospace().color(INK));
                            if ui.small_button("⟳").on_hover_text("Neu einlesen").clicked() {
                                refresh = true;
                            }
                        });
                        if ui
                            .checkbox(&mut self.cfg.git_blog_only, "Nur Blog-Inhalte (content, transactions, Snippets, Tags)")
                            .on_hover_text("Ausgeschaltet: alle Änderungen im Repository werden committet")
                            .changed()
                        {
                            scope_changed = true;
                        }
                    }
                    None => {
                        ui.label(
                            RichText::new(self.git.repo_err.clone().unwrap_or_default()).color(DANGER),
                        );
                        return;
                    }
                }
                if let Some(e) = &self.git.repo_err {
                    ui.label(RichText::new(e).small().color(DANGER));
                }
                ui.separator();

                // 1) pull
                ui.horizontal(|ui| {
                    let b = egui::Button::new(RichText::new("⬇  Pull").strong()).min_size(Vec2::new(110.0, 28.0));
                    if ui.add_enabled(!busy, b).on_hover_text("git pull --rebase --autostash").clicked() {
                        action = Some(Step::Pull);
                    }
                    if running == Some(Step::Pull) {
                        ui.spinner();
                    }
                    let behind = self.git.status.behind;
                    let hint = if behind > 0 {
                        format!("{behind} neue Commit(s) auf dem Server")
                    } else {
                        "Neues vom Server holen".into()
                    };
                    ui.label(RichText::new(hint).small().color(MUTED));
                    if self.git.pulled {
                        if ui
                            .add_enabled(self.sync_rx.is_none(), egui::Button::new("🔄  Jetzt synchronisieren"))
                            .on_hover_text("Neue Artikel aus dem Blog in die App holen")
                            .clicked()
                        {
                            sync_now = true;
                        }
                    }
                });
                ui.add_space(6.0);

                // 2) changes + commit
                let st = &self.git.status;
                let n = st.changes.len() + st.other.len();
                ui.label(
                    RichText::new(format!("Änderungen seit dem letzten Commit ({})", st.changes.len()))
                        .strong()
                        .color(INK),
                );
                egui::Frame::new()
                    .fill(LISTBG)
                    .stroke(Stroke::new(1.0, LINE))
                    .corner_radius(CornerRadius::same(6))
                    .inner_margin(Margin::same(8))
                    .show(ui, |ui| {
                        ui.set_width(ui.available_width());
                        egui::ScrollArea::vertical().id_salt("git_changes").max_height(140.0).show(ui, |ui| {
                            if n == 0 {
                                ui.label(RichText::new("Nichts zu committen – alles gespeichert.").color(MUTED));
                            }
                            for c in &st.changes {
                                ui.horizontal(|ui| {
                                    let (txt, col) = match c.kind {
                                        Kind::Created => ("＋ neu", OK),
                                        Kind::Changed => ("✏ geändert", ACCENT),
                                        Kind::Deleted => ("✖ gelöscht", DANGER),
                                    };
                                    ui.label(RichText::new(txt).small().color(col));
                                    ui.label(RichText::new(&c.title).color(INK));
                                    ui.label(RichText::new(&c.dir).small().monospace().color(MUTED));
                                });
                            }
                            if !st.other.is_empty() {
                                ui.label(
                                    RichText::new(format!(
                                        "+ {} weitere Datei(en): Transaktionen, Snippets, Tags",
                                        st.other.len()
                                    ))
                                    .small()
                                    .color(MUTED),
                                );
                            }
                        });
                    });
                ui.add_space(4.0);
                ui.horizontal(|ui| {
                    ui.label(RichText::new("Commit-Nachricht").color(MUTED));
                    if self.git.message_edited && ui.small_button("Vorschlag wiederherstellen").clicked() {
                        reset_msg = true;
                    }
                });
                let r = ui.add(
                    egui::TextEdit::multiline(&mut self.git.message)
                        .font(egui::TextStyle::Monospace)
                        .desired_rows(5)
                        .desired_width(f32::INFINITY),
                );
                if r.changed() {
                    self.git.message_edited = true;
                }
                ui.horizontal(|ui| {
                    let can = !busy && n > 0 && !self.git.message.trim().is_empty();
                    let b = egui::Button::new(RichText::new("✔  Commit").strong().color(Color32::WHITE))
                        .fill(if can { ACCENT } else { MUTED })
                        .min_size(Vec2::new(110.0, 28.0));
                    if ui.add_enabled(can, b).clicked() {
                        action = Some(Step::Commit);
                    }
                    if running == Some(Step::Commit) {
                        ui.spinner();
                    }
                    ui.label(
                        RichText::new("Erste Zeile: zuletzt geänderter Eintrag; darunter neu / geändert / gelöscht")
                            .small()
                            .color(MUTED),
                    );
                });
                ui.add_space(6.0);

                // 3) push
                ui.horizontal(|ui| {
                    let ahead = self.git.status.ahead;
                    let b = egui::Button::new(RichText::new("⬆  Push").strong()).min_size(Vec2::new(110.0, 28.0));
                    if ui.add_enabled(!busy, b).on_hover_text("git push").clicked() {
                        action = Some(Step::Push);
                    }
                    if running == Some(Step::Push) {
                        ui.spinner();
                    }
                    let hint = if ahead > 0 {
                        format!("{ahead} Commit(s) noch nicht auf dem Server")
                    } else {
                        "Alles auf dem Server".into()
                    };
